select * from (values
('Krea','이미지·영상·3D 생성과 실시간 편집·업스케일을 한곳에서 제공하는 AI #이미지생성 #AI영상 #업스케일 #API','Krea는 입력과 드로잉을 실시간 이미지로 만들고 여러 이미지·영상 모델, 생성형 편집, 3D·립싱크, LoRA 학습과 노드 기반 워크플로를 제공하는 크리에이티브 AI 제품군입니다.','https://www.krea.ai/','https://www.krea.ai/favicon.ico','Freemium','$0','Free 일 100유닛 · Basic 월 $9',array['Free는 매일 100 compute units와 기본 실시간 모델을 제공합니다.','Basic은 월 $9에 월 5,000유닛, Pro는 월 $35에 20,000유닛입니다.','API는 앱 유닛과 별도 선불 잔액에서 생성 건별 달러 요금으로 과금됩니다.'],'USD','https://www.krea.ai/pricing',now(),'Full Support',true,true,false,false,false,'official_sources','공식 제품·가격·API 자료를 확인했습니다. 생성 품질, 한국어 프롬프트와 API 호출은 직접 테스트하지 않았습니다.',false,true,'https://www.krea.ai/features/api','Native','general',array['실시간 이미지 생성','이미지·영상 생성·편집','업스케일·LoRA'],array['3D·립싱크','노드 워크플로','생성 API'],array['여러 생성 모델을 한 화면에서 사용','무료 일일 크레딧','앱과 별도 종량 API 제공'],array['이미지와 영상을 함께 제작하는 크리에이터','생성 미디어를 제품에 연결하는 개발자'],array['모델마다 compute unit 소비량이 다릅니다.','앱 구독과 API 잔액은 공유되지 않습니다.','상업 이용은 Basic 이상 라이선스 조건을 확인해야 합니다.'],array['https://www.krea.ai/pricing','https://www.krea.ai/features/api'],now(),now()),
('Photoroom','상품 사진의 배경 제거·합성·보정과 가상 모델 이미지를 만드는 AI #상품사진 #배경제거 #이미지편집 #API','Photoroom은 상품 사진 배경 제거, AI 배경·그림자·리터치·확장과 가상 패션 모델, 배치 편집을 제공하며 REST API와 MCP로 자동화할 수 있습니다.','https://www.photoroom.com/','https://www.photoroom.com/favicon.ico','Freemium','$0','무료 시작 · Pro 연간 결제 8,000 AI크레딧/월',array['무료로 시작할 수 있으며 유료 가격은 지역과 결제 화면에 따라 표시됩니다.','Pro는 월 8,000 AI크레딧·1,000 exports, Max는 25,000크레딧·3,000 exports를 제공합니다.','API·MCP 사용량은 앱 내보내기와 별도이며 유료 플랜에 API 요율용 지갑이 포함됩니다.'],'USD','https://www.photoroom.com/pricing',now(),'Full Support',true,true,false,false,false,'official_sources','공식 제품·가격 자료를 확인했습니다. 지역별 결제액, 한국어 편집과 API는 직접 테스트하지 않았습니다.',false,true,'https://www.photoroom.com/api','Native','specialized',array['배경 제거·상품 보정','AI 배경·가상 모델','배치 이미지 편집'],array['영상 생성','REST API','MCP'],array['전자상거래 상품 사진에 특화','핵심 편집 도구 무제한 범위','앱·API·MCP 선택'],array['상품 이미지를 대량 제작하는 판매자','사진 편집을 자동화하는 커머스 개발팀'],array['가격과 크레딧은 지역별로 다를 수 있습니다.','AI크레딧과 export 한도가 별도로 적용됩니다.','API·MCP 사용량은 앱 할당량과 구분해야 합니다.'],array['https://www.photoroom.com/pricing','https://www.photoroom.com/api'],now(),now()),
('Magnific','다양한 이미지·영상·오디오 모델과 업스케일·편집을 통합한 제작 플랫폼 #이미지생성 #AI영상 #업스케일 #API','Magnific은 여러 생성 모델과 이미지·영상 편집, 고해상도 업스케일, 음악·음성·효과음, 스톡 자산을 Spaces·MCP·API와 함께 제공하는 통합 크리에이티브 플랫폼입니다.','https://www.magnific.com/','https://www.magnific.com/favicon.ico','Paid',null,'Premium 연간 결제 지역별 가격 · 크레딧 1년 유효',array['Premium은 연간 크레딧과 이미지·영상·오디오 모델, 상업 라이선스를 제공합니다.','표시 가격은 접속 지역 통화와 세금에 따라 달라집니다.','모델별 크레딧 소비량이 다르며 API도 크레딧 기반으로 사용합니다.'],'USD','https://www.magnific.com/pricing',now(),'Full Support',true,true,false,false,false,'official_sources','공식 제품·가격 페이지를 확인했습니다. 지역 가격, 생성 품질과 API 호출은 직접 테스트하지 않았습니다.',false,true,'https://www.magnific.com/api','Augmented','general',array['다중 모델 미디어 생성','이미지·영상 업스케일','생성형 편집'],array['음악·음성 생성','스톡 자산','API·MCP'],array['생성과 편집·스톡을 한 구독에 통합','연간 크레딧이 월별로 소멸하지 않음','상업용 제작 기능'],array['여러 미디어 모델을 비교 사용하는 제작자','대량 콘텐츠를 만드는 스튜디오'],array['가격이 지역 통화로 달라 직접 확인이 필요합니다.','고급 영상 모델은 많은 크레딧을 소비합니다.','무제한 표기 모델에도 공정 사용 조건이 적용될 수 있습니다.'],array['https://www.magnific.com/pricing'],now(),now()),
('Topaz Photo','사진의 노이즈·흐림·저해상도와 얼굴·텍스트를 AI로 복원하는 도구 #사진보정 #업스케일 #노이즈제거 #API','Topaz Photo는 로컬 또는 클라우드에서 노이즈 제거, 선명화, 업스케일, 조명·색상 보정, 얼굴·텍스트 복원과 생성형 이미지 수정을 제공하는 전문 사진 개선 도구입니다.','https://www.topazlabs.com/topaz-photo-ai','https://www.topazlabs.com/favicon.ico','Paid','$39','Topaz Photo 월 $39 · Studio 연 $399',array['Topaz Photo는 월 $39에 로컬·클라우드 이미지 렌더링을 제공합니다.','Topaz Studio는 연 $399에 Photo·Video·Gigapixel과 웹 앱을 포함합니다.','개발자 API는 별도 크레딧 방식이며 처리 설정에 따라 사용량이 달라집니다.'],'USD','https://www.topazlabs.com/pricing',now(),'None',true,true,false,false,false,'official_sources','공식 제품·가격·API 문서를 확인했습니다. 실제 복원 품질과 API 호출은 직접 테스트하지 않았습니다.',false,true,'https://developer.topazlabs.com/','Native','specialized',array['노이즈 제거·선명화','사진 업스케일','얼굴·텍스트 복원'],array['조명·색상 보정','생성형 수정','이미지·영상 API'],array['사진 복원에 특화된 AI 모델','로컬 처리 선택','전문 워크플로와 API 제공'],array['저화질 사진을 복원하는 사진가','이미지 개선을 서비스에 연결하는 개발자'],array['무료 플랜 없이 유료 구독 중심입니다.','기업 매출에 따라 별도 Pro 라이선스가 필요합니다.','과도한 복원은 원본에 없는 세부를 생성할 수 있습니다.'],array['https://www.topazlabs.com/pricing','https://developer.topazlabs.com/whats-the-pricing'],now(),now()),
('D-ID','사진과 텍스트·음성으로 말하는 디지털 휴먼 영상을 만드는 AI #AI아바타 #AI영상 #립싱크 #API','D-ID Creative Reality Studio는 준비된 아바타나 업로드한 얼굴 이미지에 텍스트·음성을 결합해 말하는 영상을 만들고 실시간 Visual Agent와 영상 생성 API를 제공합니다.','https://www.d-id.com/creative-reality-studio/','https://www.d-id.com/favicon.ico','Freemium','$0','무료 체험 · 유료 플랜 가격은 공식 결제 화면 확인',array['무료 체험으로 Studio의 아바타 영상을 시험할 수 있습니다.','영상 사용량은 15초 단위로 올림되어 플랜의 분에서 차감됩니다.','API 사용도 Studio와 같은 분 잔액에서 차감되며 유효 크레딧이 필요합니다.'],'USD','https://www.d-id.com/pricing/studio/',now(),'Full Support',true,true,false,false,false,'official_sources','공식 제품·가격 FAQ·API 자료를 확인했습니다. 영상 생성, 한국어 음성과 API는 직접 테스트하지 않았습니다.',false,true,'https://docs.d-id.com/','Native','specialized',array['말하는 AI 아바타','사진 애니메이션','실시간 Visual Agent'],array['다국어 음성','영상 번역','생성·스트리밍 API'],array['한 장의 얼굴 이미지로 발표 영상 제작','Studio와 API 제공','실시간 디지털 휴먼 지원'],array['교육·마케팅 아바타 영상을 만드는 팀','디지털 휴먼을 제품에 넣는 개발자'],array['영상은 최대 길이와 업로드 크기 제한이 있습니다.','Trial·Lite 결과에는 워터마크가 표시됩니다.','초상권·음성권과 합성 미디어 고지가 필요합니다.'],array['https://www.d-id.com/creative-reality-studio/','https://www.d-id.com/pricing/studio/'],now(),now()),
('LALAL.AI','음악·영상에서 보컬과 악기·음성을 분리하고 잡음을 제거하는 AI #음원분리 #보컬제거 #오디오편집 #API','LALAL.AI는 오디오와 영상에서 보컬, 반주, 드럼, 베이스 등 선택한 stem을 분리하고 음성 정리·노이즈 제거를 제공하며 대량 처리를 위한 API를 지원합니다.','https://www.lalal.ai/','https://www.lalal.ai/favicon.ico','Freemium','$0','Starter 무료 10분 · Lite 월 $9.99',array['Starter는 relaxed queue 10분으로 분리 품질을 시험하지만 전체 다운로드는 제한됩니다.','Lite는 월 $9.99, Pro는 월 $19.99입니다.','추가 분량은 일회성 Top-Up으로 구매할 수 있고 기업·API는 별도 조건이 적용됩니다.'],'USD','https://www.lalal.ai/stem-splitter/',now(),'Full Support',true,true,false,false,false,'official_sources','공식 제품·가격·API 자료를 확인했습니다. 실제 음원 분리 품질과 API는 직접 테스트하지 않았습니다.',false,true,'https://www.lalal.ai/api/','Native','specialized',array['보컬·악기 stem 분리','음성·잡음 정리','오디오·영상 처리'],array['대용량 파일','일회성 분량 구매','Stem Splitter API'],array['무료로 분리 품질 확인','다양한 악기 stem 지원','웹과 API 제공'],array['리믹스·반주를 만드는 음악 제작자','음원 분리를 서비스에 연결하는 개발자'],array['무료 플랜은 전체 결과 다운로드가 제한됩니다.','분리 결과에 잔향·왜곡이 남을 수 있습니다.','저작권이 있는 음원의 사용·배포 권리를 확인해야 합니다.'],array['https://www.lalal.ai/stem-splitter/','https://www.lalal.ai/api/'],now(),now()),
('Auphonic','음량·노이즈·에코를 자동 보정하고 전사·챕터·배포까지 처리하는 오디오 AI #오디오편집 #음질개선 #팟캐스트 #API','Auphonic은 음성 콘텐츠의 음량 평준화, 노이즈·잔향 제거, AutoEQ, 필러·침묵 제거와 다국어 전사·쇼노트를 자동 처리하고 결과 인코딩·게시를 지원합니다.','https://auphonic.com/','https://auphonic.com/favicon.ico','Freemium','$0','Free 월 2시간 · 유료 월간·일회성 시간 크레딧',array['Free는 매월 2시간 처리하며 결과에 Auphonic jingle이 포함됩니다.','월간 플랜은 9시간부터 시작하고 미사용 시간은 이월되지 않습니다.','일회성 시간 크레딧은 만료되지 않으며 API 접근은 무료 플랜에도 포함됩니다.'],'USD','https://auphonic.com/pricing',now(),'Full Support',true,true,false,false,false,'official_sources','공식 제품·가격·API 도움말을 확인했습니다. 오디오 처리 품질, 한국어 전사와 API는 직접 테스트하지 않았습니다.',false,true,'https://auphonic.com/api/','Native','specialized',array['자동 음량·음질 보정','노이즈·잔향 제거','전사·쇼노트'],array['다중 트랙','자동 게시','API·CLI'],array['월 2시간 무료 후처리','팟캐스트 배포 흐름 자동화','무료 플랜도 API 사용 가능'],array['팟캐스트·강의 음성을 정리하는 제작자','오디오 후처리를 자동화하는 서비스'],array['무료 결과에는 브랜드 jingle이 들어갑니다.','짧은 파일도 최소 3분 사용량이 차감됩니다.','자동 필러 제거 후 전체 음성을 청취 검수해야 합니다.'],array['https://auphonic.com/pricing','https://us1.auphonic.com/help/web/'],now(),now()),
('AssemblyAI','실시간·녹음 음성을 전사하고 화자·개체·요약을 분석하는 개발자 API #음성인식 #전사 #보이스AI #API','AssemblyAI는 사전 녹음과 실시간 음성의 전사, 화자 분리, 주요 용어·개체 감지, 의료 모드와 Voice Agent용 스트리밍을 제공하는 개발자 중심 음성 AI API입니다.','https://www.assemblyai.com/','https://www.assemblyai.com/favicon.ico','Paid','$0.15','무료 크레딧 · Universal-2 시간당 $0.15',array['가입 후 무료 크레딧으로 카드 없이 API를 시작할 수 있습니다.','Universal-2 사전 녹음 전사는 시간당 $0.15, Universal-3 Pro는 시간당 $0.21입니다.','화자 분리·의료 모드 등 부가 기능은 시간당 별도 요금이며 실제 초 단위로 비례 과금됩니다.'],'USD','https://www.assemblyai.com/pricing',now(),'Full Support',true,true,false,false,false,'official_sources','공식 가격·API·지원 문서를 확인했습니다. 실제 API 호출과 한국어 정확도는 직접 테스트하지 않았습니다.',false,true,'https://www.assemblyai.com/docs/api-reference/overview/','Native','specialized',array['사전 녹음 음성 전사','실시간 음성 인식','화자·음성 이해'],array['Voice Agent API','의료 모드','SDK·EU 엔드포인트'],array['초 단위 종량 과금','다국어 전사 모델','개발자용 음성 기능 통합'],array['음성 전사·콜 분석 서비스를 만드는 개발자','실시간 보이스 에이전트를 구축하는 팀'],array['고급 분석 기능은 기본 전사료에 추가됩니다.','스트리밍 세션을 종료하지 않으면 불필요한 과금이 발생할 수 있습니다.','의료·법률 전사는 전문가 검토가 필요합니다.'],array['https://www.assemblyai.com/pricing','https://www.assemblyai.com/docs/api-reference/overview/'],now(),now()),
('remove.bg','사진의 인물·상품 배경을 자동 제거하고 API로 대량 처리하는 AI #배경제거 #이미지편집 #상품사진 #API','remove.bg는 사진 속 전경을 자동 인식해 배경을 투명하게 만들거나 교체하며 웹, 데스크톱 앱, Photoshop 확장과 API로 단일·대량 이미지를 처리합니다.','https://www.remove.bg/','https://www.remove.bg/favicon.ico','Freemium','$0','무료 저해상도 결과 · 고해상도 크레딧 가격은 공식 화면 확인',array['웹에서 저해상도 배경 제거 결과를 무료로 받을 수 있습니다.','고해상도 다운로드와 API 처리는 크레딧을 사용합니다.','구독·종량 크레딧의 최신 가격은 지역별 공식 가격 화면에서 확인해야 합니다.'],'USD','https://www.remove.bg/pricing',now(),'Full Support',true,true,false,false,false,'official_sources','공식 제품·가격·API 페이지를 확인했습니다. 경계선 품질, 한국어 UI와 API는 직접 테스트하지 않았습니다.',false,true,'https://www.remove.bg/api','Native','specialized',array['자동 배경 제거','배경 교체','대량 이미지 처리'],array['데스크톱 앱','Photoshop 확장','REST API'],array['간단한 단일 목적 작업','무료 품질 확인','다양한 제작 도구와 API'],array['상품·프로필 사진 배경을 지우는 사용자','이미지 파이프라인을 자동화하는 개발자'],array['무료 다운로드는 해상도가 제한됩니다.','머리카락·반투명 물체의 경계 결과를 검수해야 합니다.','고해상도와 API는 별도 크레딧이 필요합니다.'],array['https://www.remove.bg/pricing','https://www.remove.bg/api'],now(),now())
) as seed(name,description,full_description,url,logo_url,pricing_type,pricing_start_at,pricing_summary,pricing_details,pricing_currency,pricing_url,pricing_verified_at,korean_support_level,is_verified,source_verified,hands_on_verified,api_tested,korean_tested,verification_level,verification_notes,is_domestic,has_api,api_url,ai_type,tool_scope,primary_features,secondary_features,key_benefits,best_for,limitations,verification_sources,verified_at,updated_at)
where not exists(select 1 from public.tools where lower(tools.url)=lower(seed.url));

with assignments(tool_url,category_slug) as (values
('https://www.krea.ai/','design-art'),('https://www.krea.ai/','video-audio'),
('https://www.photoroom.com/','design-art'),('https://www.photoroom.com/','business-marketing'),
('https://www.magnific.com/','design-art'),('https://www.magnific.com/','video-audio'),
('https://www.topazlabs.com/topaz-photo-ai','design-art'),
('https://www.d-id.com/creative-reality-studio/','video-audio'),('https://www.d-id.com/creative-reality-studio/','business-marketing'),
('https://www.lalal.ai/','video-audio'),('https://auphonic.com/','video-audio'),
('https://www.assemblyai.com/','video-audio'),('https://www.assemblyai.com/','development'),
('https://www.remove.bg/','design-art'),('https://www.remove.bg/','business-marketing')
)
insert into public.tool_categories(tool_id,category_id)
select tools.id,categories.id from assignments
join public.tools on lower(tools.url)=lower(assignments.tool_url)
join public.categories on lower(categories.slug)=lower(assignments.category_slug)
on conflict(tool_id,category_id) do nothing;
